DIGITS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

def to_base(x, b):
    if x == 0: return '0'
    res = ''
    while x:
        res = DIGITS[x % b] + res
        x //= b
    return res

def from_base(s, b):
    val = 0
    for ch in s:
        val = val * b + DIGITS.index(ch)
    return val
